{"command":"ls -d /home/hatch/agents/agent-d737decc* 2>/dev/null; f=$(ls /home/hatch/agents/agent-d737decc*/sessions/*.jsonl 2>/dev/null | head -1); echo "file: $f"; python3 <<'EOF'
import json, glob
fs=glob.glob('/home/hatch/agents/agent-d737decc*/sessions/*.jsonl')
print('matches:',len(fs))
if fs:
    f=fs[0]
    items=[json.loads(l) for l in open(f)]
    print('items:',len(items))
    def dt(o):
        if isinstance(o,str): return o
        if isinstance(o,dict): return ' '.join(dt(v) for v in o.values())
        if isinstance(o,list): return ' '.join(dt(v) for v in o)
        return ''
    canned=0; roles={}
    for it in items[1:]:
        m=it['item']; t=dt(m)
        roles[(m.get('type'),m.get('role'))]=roles.get((m.get('type'),m.get('role')),0)+1
        if 'A safety policy refused' in t: canned+=1
    print('canned bodies in session:',canned)
    print('role histogram:',dict(list(roles.items())[:12]))
    # last 3 items
    for it in items[-3:]:
        m=it['item']; print('tail:',m.get('type'),m.get('role'),'|',dt(m)[:80].replace('\n',' '))
EOF"}

