{"args":{},"script":"export const meta = { name: "pong-control-5x", description: "5 consecutive clean-context PONG probes, verifying each result body", phases: ["probe"] };

const probes = [];
for (let n = 1; n <= 5; n++) {
  const out = agent("Output the exact string PONG-" + n + " and nothing else.", { key: "pong-" + n, label: "PONG probe " + n, timeoutMs: 60000 });
  probes.push({ n: n, out: out });
}
