          "parameters": {
            "additionalProperties": false,
            "properties": {
              "runId": {
                "description": "Workflow run id, as returned by a launch or listed by workflow.list_runs. The run must be paused; a synchronous run's resume waits for it to resolve.",
                "type": "string"
              }
            },
            "required": [
              "runId"
            ],
            "type": "object"
