          "name": "workflow.stop",
          "description": "Stop one workflow run by run id. Stopping is terminal: the run's remaining work is cancelled and a stopped run must never be resumed or relaunched; the resumeFromRunId retry path exists only for failed runs. Only runs belonging to this root session can be controlled. To suspend a run you intend to continue, use workflow.pause instead; to stop only one child agent while the run continues, use workflow.stop_agent.",
          "parameters": {
            "additionalProperties": false,
            "properties": {
              "runId": {
                "description": "Workflow run id, as returned by a launch or listed by workflow.list_runs. Stopping is terminal; a stopped run can never be resumed or relaunched.",
