              "runId"
            ],
            "type": "object"
          }
        },
        {
          "name": "workflow.stop_agent",
          "description": "Stop one child agent call inside a workflow run without stopping the run. Requires the run id and the callId of the child agent call; workflow.view_run lists the run's child calls and their call ids. The run itself keeps going; use workflow.stop to end the whole run. Only runs belonging to this root session can be controlled.",
          "parameters": {
