"""Fleet job audit: walks all 20260916* job dirs, classifies state/cause/action."""
import json, os, sys, time, csv

JOBS = "/home/toxic/fleet/jobs"
NOW = time.time()
rows = []

def read_text(p, limit=None):
    try:
        with open(p, "r", errors="replace") as f:
            d = f.read()
        return d[:limit] if limit else d
    except OSError:
        return ""

def tail_lines(p, n):
    d = read_text(p)
    lines = [l for l in d.splitlines() if l.strip()]
    return lines[-n:] if lines else []

for jid in sorted(os.listdir(JOBS)):
    if not jid.startswith("20260916"):
        continue
    d = os.path.join(JOBS, jid)
    if not os.path.isdir(d) or not os.path.isfile(os.path.join(d, "spec.json")):
        continue
    spec = json.loads(read_text(os.path.join(d, "spec.json")) or "{}")
    cmd = spec.get("cmd", [])
    cmd_str = " ".join(cmd)
    status = read_text(os.path.join(d, "status")).strip()
    pid_s = read_text(os.path.join(d, "pid")).strip()
    pid = int(pid_s) if pid_s.isdigit() else None
    wrapper_alive = False
    if pid:
        try:
            os.kill(pid, 0)
            wrapper_alive = True
        except OSError:
            pass
    hb_raw = read_text(os.path.join(d, "heartbeat")).strip()
    try:
        hb_age = int(NOW - float(hb_raw))
    except (ValueError, TypeError):
        hb_age = None
    res = {}
    try:
        res = json.loads(read_text(os.path.join(d, "result.json")) or "{}")
    except ValueError:
        pass
    exit_code = res.get("exit_code")
    duration = res.get("duration_s")
    werr = read_text(os.path.join(d, "wrapper.err"))
    werr_sig = ""
    for l in werr.splitlines():
        if "Error" in l or "error" in l.lower() or "Traceback" in l:
            werr_sig = l.strip()
    if not werr_sig and werr.strip():
        werr_sig = werr.strip().splitlines()[-1][:120]
    out_tail = tail_lines(os.path.join(d, "stdout.log"), 3)
