{"content":"#!/usr/bin/env python3
"""Build the -1/0 seed list DIRECTLY from chat history (session JSONL),
then measure the exact offending token set with tiktoken cl100k_base.

Method (auditable):
- Walk session items in seq order for the side chat (802811a3) and main chat (5a4f76c0).
- Label -1: message body md5 matches a known storm digest (byte-identical).
- Label 0: everything else.
- echo_chain: whether any of the 5 preceding turns is itself a storm turn
  (refusal-on-refusal / checkpoint carry-forward).
- Pre-onset corpus: nearest preceding USER turn before each -1 turn.
- Benign corpus: all other user turns.
- Per-token smoothed likelihood ratio:
    LR(t) = ((c_pre+1)/(P+2)) / ((c_benign+1)/(B+2))
  ranked descending; min support 5 in pre-onset.
- Quarantine: only digests, lengths, counts, token fragments on disk.
  Verbatim bodies are never written.

Output: seed_list_chat.json, offending_tokens.json
"""
import json, hashlib, os
from collections import Counter
import tiktoken

STORMS = {
    "b4aefd29108f232f9c0d5a4b030215c1",  # 384-char primary
    "582bcbd080daeb3f826c45ed4a83b265",  # 96-char assistant variant
}
SESSIONS = {
    "side": "/home/hatch/agents/agent-802811a3-2226-42dd-b347-9754def28d22/sessions/802811a3-2226-42dd-b347-9754def28d22.jsonl",
    "main": "/home/hatch/agents/agent-5a4f76c0-e3a4-4069-ba6f-3113917102dc/sessions/5a4f76c0-e3a4-4069-ba6f-3113917102dc.jsonl",
}
OUT = os.path.expanduser("~/workspace/do-the-thing/token")
os.makedirs(OUT, exist_ok=True)

enc = tiktoken.get_encoding("cl100k_base")

def md5(s: str) -> str:
    return hashlib.md5(s.encode("utf-8", "replace")).hexdigest()

turns = []
for name, path in SESSIONS.items():
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            try:
                o = json.loads(line)
            except json.JSONDecodeError:
                continue
            if o.get("type") != "item":
                continue
            it = o.get("item") or {}
            if it.get("type") != "message":
                continue
            text = it.get("text") or ""
            if not text:
                continue
            turns.append({
                "session": name, "seq": o.get("seq"), "role": it.get("role"),
                "md5": md5(text), "len": len(text),
                "ts": o.get("created_at"), "text": text,
            })

for t in turns:
    t["label"] = -1 if t["md5"] in STORMS else 0

md5s = [t["md5"] for t in turns]
n1 = 0
for i, t in enumerate(turns):
    if t["label"] == -1:
        n1 += 1
        t["echo_chain"] = any(m in STORMS for m in md5s[max(0, i - 5):i])

pre_texts, benign_texts = [], []
for i, t in enumerate(turns):
    if t["label"] == -1:
        for j in range(i - 1, -1, -1):
            if turns[j]["role"] == "user":
                pre_texts.append(turns[j]["text"])
                break
    elif t["role"] == "user":
        benign_texts.append(t["text"])

pre_ids, ben_ids = Counter(), Counter()
for s in pre_texts:
    pre_ids.update(enc.encode(s))
for s in benign_texts:
    ben_ids.update(enc.encode(s))
P, B = sum(pre_ids.values()), sum(ben_ids.values())

rows = []
for tid, c in pre_ids.items():
    if c < 5:
        continue
    b = ben_ids.get(tid, 0)
    lr = ((c + 1) / (P + 2)) / ((b + 1) / (B + 2))
    rows.append((tid, c, b, lr))
rows.sort(key=lambda r: -r[3])

offending = []
for tid, c, b, lr in rows[:80]:
    try:
        tok = enc.decode([tid])
    except Exception:
        tok = f"<id:{tid}>"
    conf = "high" if (lr >= 8 and c >= 10) else ("medium" if lr >= 4 else "low")
    offending.append({
        "token": tok, "token_id": tid,
        "pre_onset_count": c, "benign_count": b,
        "likelihood_ratio": round(lr, 3), "confidence": conf,
    })

slim = []
for t in turns:
    d = {k: t[k] for k in ("session", "seq", "role", "md5", "len", "ts", "label")}
    if t["label"] == -1:
        d["echo_chain"] = t["echo_chain"]
    slim.append(d)
json.dump(slim, open(os.path.join(OUT, "seed_list_chat.json"), "w"))
json.dump({
    "method": "turn-by-turn session JSONL; LR(t)=((c_pre+1)/(P+2))/((c_benign+1)/(B+2)); min support 5",
    "corpus": {"pre_onset_user_turns": len(pre_texts), "benign_user_turns": len(benign_texts),
               "pre_onset_tokens": P, "benign_tokens": B,
               "storm_turns": n1,
               "echo_chain_rate": round(sum(1 for t in turns if t.get("echo_chain")) / max(n1, 1), 3)},
    "note": "Measured correlation only. Pre-onset = nearest user turn before each storm turn.",
    "offending_tokens": offending,
}, open(os.path.join(OUT, "offending_tokens.json"), "w"), indent=1)

print(f"turns={len(turns)} storm_turns={n1} pre_user_turns={len(pre_texts)} benign_user_turns={len(benign_texts)}")
print(f"top-15 tokens:")
for o in offending[:15]:
    print(f"  {o['token']!r:24} id={o['token_id']:<7} pre={o['pre_onset_count']:<5} ben={o['benign_count']:<6} LR={o['likelihood_ratio']:<8} {o['confidence']}")
","path":"~/workspace/do-the-thing/token/build_seed.py"}

{"content":"#!/usr/bin/env python3
"""w2-replay-detector: detect composite-replay turns in session history.
Plan: (1) load sessions/*.jsonl from SEEDS; (2) detector: a user turn is a
composite replay if it contains a >=120-char verbatim substring of an EARLIER
user turn in the same session AND its first 300 chars share no 40-char
substring with any earlier turn (novel formal framing); (3) report detections
as (session, seq) with metrics; (4) RESULT.json.
Quarantine: write seqs/metrics only, never message bodies.
"""
import json, os, time

WORK = os.path.dirname(os.path.abspath(__file__))
SEEDS = "/home/toxic/.fleet-bus/coord/work/seeds"

def load(session):
    turns = []
    path = os.path.join(SEEDS, "sessions", f"{session}.jsonl")
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            try:
                o = json.loads(line)
            except json.JSONDecodeError:
                continue
            if o.get("type") != "item":
                continue
            it = o.get("item") or {}
            if it.get("type") != "message" or it.get("role") != "user":
                continue
            txt = it.get("text") or ""
            if txt:
                turns.append((o.get("seq"), txt))
    return turns

def is_replay(idx, turns):
    seq, txt = turns[idx]
    if len(txt) < 200:
        return None
    prefix = txt[:300]
    # (b) novel framing: no 40-char prefix chunk appears earlier
    for j in range(idx):
        earlier = turns[j][1]
        for k in range(0, min(300, len(prefix) - 39), 40):
            if prefix[k:k + 40] in earlier:
                break
        else:
            continue
        break
    else:
        novel = True
        # (a) verbatim quote: any 120-char window of txt[300:] in an earlier turn
        for j in range(idx):
            earlier = turns[j][1]
            body = txt[300:]
            for k in range(0, max(1, len(body) - 119), 60):
                if body[k:k + 120] in earlier:
                    return {"seq": seq, "quoted_from_seq": turns[j][0],
                            "turn_len": len(txt)}
        return None
    return None

detections = []
for sess in ("side", "main"):
    turns = load(sess)
    for i in range(len(turns)):
        hit = is_replay(i, turns)
        if hit:
            hit["session"] = sess
            detections.append(hit)

r = {"lane": "w2-replay-detector",
     "ts_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
     "claims": [f"composite-replay detector found {len(detections)} candidate turns"],
     "evidence": {"detections": detections[:50], "n_user_turns_scanned": "see sessions"},
     "proof_files": ["brief.py"]}
json.dump(r, open(os.path.join(WORK, "RESULT.json"), "w"), indent=1)
print(json.dumps(r, indent=1)[:3000])
